create or replace function public.staff_directory() returns table(user_id uuid,email text) language plpgsql stable security definer set search_path = '' as $$ begin if not public.can_manage_site() then raise exception 'Staff verification required'; end if; return query select u.id,u.email::text from auth.users u where public.is_staff(u.id); end $$; revoke all on function public.staff_directory() from public, anon; grant execute on function public.staff_directory() to authenticated;